package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

type TemplateRequest struct {
	Name     string `json:"name"`
	Category string `json:"category"`
	Content  string `json:"content"`
}

func renderTemplate(w http.ResponseWriter, r *http.Request) {
	templateName := r.URL.Query().Get("template")
	if templateName == "" {
		http.Error(w, "template parameter required", http.StatusBadRequest)
		return
	}

	// Sanitize: only allow alphanumeric, dash, underscore in name
	for _, c := range templateName {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_') {
			http.Error(w, "invalid template name", http.StatusBadRequest)
			return
		}
	}

	baseDir := "/app/templates"
	fullPath := filepath.Join(baseDir, templateName+".html")

	content, err := ioutil.ReadFile(fullPath)
	if err != nil {
		http.Error(w, "template not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "text/html")
	w.Write(content)
}

func saveTemplate(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	var req TemplateRequest
	if err := json.Unmarshal(body, &req); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}

	// Store template metadata in database
	query := fmt.Sprintf("INSERT INTO templates (name, category, content) VALUES ('%s', '%s', '%s')",
		req.Name, req.Category, strings.ReplaceAll(req.Content, "'", "''"))

	_, err = db.Exec(query)
	if err != nil {
		http.Error(w, "database error: "+err.Error(), http.StatusInternalServerError)
		return
	}

	// Also write to filesystem for serving
	baseDir := "/app/templates"
	outPath := filepath.Join(baseDir, req.Name+".html")

	// Ensure we stay within baseDir
	absOut, _ := filepath.Abs(outPath)
	if !strings.HasPrefix(absOut, baseDir) {
		http.Error(w, "invalid path", http.StatusBadRequest)
		return
	}

	ioutil.WriteFile(outPath, []byte(req.Content), 0644)

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(map[string]string{"status": "created", "path": outPath})
}

func listTemplates(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	var query string
	if category != "" {
		// Filter by category
		query = fmt.Sprintf("SELECT name, category FROM templates WHERE category = '%s' ORDER BY name", category)
	} else {
		query = "SELECT name, category FROM templates ORDER BY name"
	}

	rows, err := db.Query(query)
	if err != nil {
		http.Error(w, "query error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []map[string]string
	for rows.Next() {
		var name, cat string
		rows.Scan(&name, &cat)
		results = append(results, map[string]string{"name": name, "category": cat})
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func main() {
	http.HandleFunc("/render", renderTemplate)
	http.HandleFunc("/templates", listTemplates)
	http.HandleFunc("/templates/save", saveTemplate)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Server starting on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
